interface RichExport {
    default String mediaType() { return normalized(" TEXT/PLAIN "); }
    static boolean supported(String type) { return type != null && !type.isBlank(); }
    private String normalized(String value) { return value.trim().toLowerCase(); }
}
class RichExporter implements RichExport {}
public class InterfaceMethodEvolutionDemo {
    public static void main(String[] args) { var e = new RichExporter(); System.out.println(e.mediaType() + " " + RichExport.supported(e.mediaType())); }
}
